LOCALIZED["ko"]["superintendent"]="건물 관리자는 엘리베이터 수리를 준비했다."

def main():
    phrase=json.loads(PHRASE_PATH.read_text(encoding='utf-8')); translations=phrase.setdefault('translations',{}); expected=set(WORDS)
    assert all(set(d)==expected for d in LOCALIZED.values())
    changed=0
    for item in json.loads((ROOT/'app/src/main/assets/vocabulary.json').read_text(encoding='utf-8')):
        word=str(item.get('word','')).casefold()
        if word not in expected: continue
        ex=translations.setdefault(f"builtin:{item['id']}",{}).setdefault('example',{})
        for lang,value in [('en',EN[word]),('ja',JA[word])]+[(lang,LOCALIZED[lang][word]) for lang in LOCALIZED]:
            if ex.get(lang)!=value: ex[lang]=value; changed+=1
    PHRASE_PATH.write_text(json.dumps(phrase,ensure_ascii=False,indent=1)+'\n',encoding='utf-8'); print(f'reviewed multilingual examples 700+ 951-1000: {len(WORDS)} terms, {changed} fields')
if __name__=='__main__': main()
